import React, { useState, useEffect } from 'react';
import Modal from '../common/Modal';

const publicationTypes = ['Book', 'eBook', 'Magazine', 'Journal', 'Research Paper'];
const priorities = ['Low', 'Medium', 'High', 'Urgent'];
const statuses = ['Planning', 'Active', 'Hold', 'Completed', 'Cancelled'];

const ProjectFormModal = ({ isOpen, onClose, onSubmit, employees = [], initialData = null, isEdit = false }) => {
  const [formData, setFormData] = useState({
    projectName: '',
    bookName: '',
    author: '',
    ISBN: '',
    publicationType: 'Book',
    category: 'General Literature',
    description: '',
    priority: 'Medium',
    status: 'Planning',
    deadline: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    assignedEmployees: [],
    estimatedBudget: 5000,
    completionPercentage: 0,
  });

  useEffect(() => {
    if (initialData) {
      setFormData({
        projectName: initialData.projectName || '',
        bookName: initialData.bookName || '',
        author: initialData.author || '',
        ISBN: initialData.ISBN || '',
        publicationType: initialData.publicationType || 'Book',
        category: initialData.category || 'General Literature',
        description: initialData.description || '',
        priority: initialData.priority || 'Medium',
        status: initialData.status || 'Planning',
        deadline: initialData.deadline ? new Date(initialData.deadline).toISOString().split('T')[0] : '',
        assignedEmployees: initialData.assignedEmployees
          ? initialData.assignedEmployees.map((e) => (typeof e === 'object' ? e._id : e))
          : [],
        estimatedBudget: initialData.estimatedBudget || 0,
        completionPercentage: initialData.completionPercentage || 0,
      });
    } else {
      setFormData({
        projectName: '',
        bookName: '',
        author: '',
        ISBN: '',
        publicationType: 'Book',
        category: 'General Literature',
        description: '',
        priority: 'Medium',
        status: 'Planning',
        deadline: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        assignedEmployees: [],
        estimatedBudget: 5000,
        completionPercentage: 0,
      });
    }
  }, [initialData, isOpen]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleEmployeeToggle = (empId) => {
    setFormData((prev) => {
      const exists = prev.assignedEmployees.includes(empId);
      if (exists) {
        return { ...prev, assignedEmployees: prev.assignedEmployees.filter((id) => id !== empId) };
      } else {
        return { ...prev, assignedEmployees: [...prev.assignedEmployees, empId] };
      }
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit(formData);
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title={isEdit ? `Edit Project - ${initialData?.projectId}` : 'Create Publication Project'}
      maxWidth="750px"
    >
      <form onSubmit={handleSubmit}>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
          <div className="form-group">
            <label className="form-label">Project Title *</label>
            <input
              type="text"
              name="projectName"
              className="form-input"
              value={formData.projectName}
              onChange={handleChange}
              required
            />
          </div>

          <div className="form-group">
            <label className="form-label">Book / Publication Name *</label>
            <input
              type="text"
              name="bookName"
              className="form-input"
              value={formData.bookName}
              onChange={handleChange}
              required
            />
          </div>

          <div className="form-group">
            <label className="form-label">Author Name *</label>
            <input
              type="text"
              name="author"
              className="form-input"
              value={formData.author}
              onChange={handleChange}
              required
            />
          </div>

          <div className="form-group">
            <label className="form-label">ISBN / ISSN Code</label>
            <input
              type="text"
              name="ISBN"
              className="form-input"
              placeholder="e.g. 978-3-16-148410-0"
              value={formData.ISBN}
              onChange={handleChange}
            />
          </div>

          <div className="form-group">
            <label className="form-label">Publication Format *</label>
            <select
              name="publicationType"
              className="form-select"
              value={formData.publicationType}
              onChange={handleChange}
            >
              {publicationTypes.map((t) => (
                <option key={t} value={t}>
                  {t}
                </option>
              ))}
            </select>
          </div>

          <div className="form-group">
            <label className="form-label">Category / Genre</label>
            <input
              type="text"
              name="category"
              className="form-input"
              value={formData.category}
              onChange={handleChange}
            />
          </div>

          <div className="form-group">
            <label className="form-label">Priority</label>
            <select name="priority" className="form-select" value={formData.priority} onChange={handleChange}>
              {priorities.map((p) => (
                <option key={p} value={p}>
                  {p}
                </option>
              ))}
            </select>
          </div>

          <div className="form-group">
            <label className="form-label">Status</label>
            <select name="status" className="form-select" value={formData.status} onChange={handleChange}>
              {statuses.map((s) => (
                <option key={s} value={s}>
                  {s}
                </option>
              ))}
            </select>
          </div>

          <div className="form-group">
            <label className="form-label">Target Deadline *</label>
            <input
              type="date"
              name="deadline"
              className="form-input"
              value={formData.deadline}
              onChange={handleChange}
              required
            />
          </div>

          <div className="form-group">
            <label className="form-label">Estimated Budget (₹ INR)</label>
            <input
              type="number"
              name="estimatedBudget"
              className="form-input"
              value={formData.estimatedBudget}
              onChange={handleChange}
            />
          </div>
        </div>

        <div className="form-group" style={{ marginTop: '12px' }}>
          <div className="flex-row" style={{ justifyContent: 'space-between', marginBottom: '6px' }}>
            <label className="form-label">Real-Time Publication Progress ({formData.completionPercentage}%)</label>
            <input
              type="number"
              min="0"
              max="100"
              name="completionPercentage"
              className="form-input"
              style={{ width: '80px', padding: '4px 8px', textAlign: 'center' }}
              value={formData.completionPercentage}
              onChange={handleChange}
            />
          </div>
          <input
            type="range"
            min="0"
            max="100"
            name="completionPercentage"
            value={formData.completionPercentage}
            onChange={handleChange}
            style={{ width: '100%', accentColor: 'var(--primary)' }}
          />
          <div className="flex-row" style={{ justifyContent: 'space-between', fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: '4px' }}>
            <span>0% Manuscript</span>
            <span>25% Editorial</span>
            <span>50% Design</span>
            <span>75% Proofreading</span>
            <span>100% Released</span>
          </div>
        </div>

        <div className="form-group">
          <label className="form-label">Assign Team Members (Publication Staff)</label>
          <div
            style={{
              maxHeight: '130px',
              overflowY: 'auto',
              border: '1px solid var(--border-color)',
              borderRadius: '10px',
              padding: '10px',
              background: 'var(--bg-input)',
              display: 'grid',
              gridTemplateColumns: '1fr 1fr',
              gap: '8px',
            }}
          >
            {employees.map((emp) => (
              <label
                key={emp._id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '8px',
                  fontSize: '0.85rem',
                  cursor: 'pointer',
                }}
              >
                <input
                  type="checkbox"
                  checked={formData.assignedEmployees.includes(emp._id)}
                  onChange={() => handleEmployeeToggle(emp._id)}
                />
                {emp.fullName} ({emp.department})
              </label>
            ))}
          </div>
        </div>

        <div className="form-group">
          <label className="form-label">Project Description</label>
          <textarea
            name="description"
            className="form-textarea"
            rows="3"
            value={formData.description}
            onChange={handleChange}
          />
        </div>

        <div className="modal-footer" style={{ padding: '16px 0 0 0' }}>
          <button type="button" className="btn btn-secondary" onClick={onClose}>
            Cancel
          </button>
          <button type="submit" className="btn btn-primary">
            {isEdit ? 'Save Project' : 'Create Project'}
          </button>
        </div>
      </form>
    </Modal>
  );
};

export default ProjectFormModal;
